) AS (
  VALUES 
    (216::BIGINT, 'Buena profe, siempre ayuda cuando se le pide. Si quiere sacar buenas notas en las evaluaciones siga bien la rúbrica. El semestre pasado los quices eran orales, pero igual las preguntas eran muy fáciles.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Aspectos de calificación claros', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2026-06-25T00:00:00+00:00'::TIMESTAMPTZ, 'eecc0c87b1d97b4395945659e678b364576f491782658c0ad5c8dcb7921bf9bf'::TEXT, ARRAY[631]::BIGINT[]),
    (216::BIGINT, 'Muy buena profe, explica todo y las evaluaciones no son difíciles, califica suave.'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2026-06-25T00:00:00+00:00'::TIMESTAMPTZ, 'a2a64a63ad948fbb0a1868192985e8a0f5edb365b96094f2ef87eb982e5b06a3'::TEXT, ARRAY[631]::BIGINT[]),
    (216::BIGINT, 'Ninguno'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Asistencia obligatoria', 'Clases largas']::TEXT[], '2024-01-25T00:00:00+00:00'::TIMESTAMPTZ, '85262f667fd365e9b787d6bd7eeea9469ab74d3ea4dc5bf7e063cb2c29f9991b'::TEXT, ARRAY[922]::BIGINT[]),
    (216::BIGINT, 'La profe es un amor de persona. Tiene formación pedagógica (lo cual casi nadie tiene en esa escuela), por lo que sus clases se sienten muy amenas. Califica justo. Ayuda muchísimo en consulta o por Teams, y tiene muchísima paciencia con uno. Participe bastante, eso ella lo agradece.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2023-12-02T00:00:00+00:00'::TIMESTAMPTZ, '566281044d07d9ae74f58f8878450c0de6a56d37c4b904f2a5206cd48dd5deef'::TEXT, ARRAY[922]::BIGINT[]),
    (216::BIGINT, 'yo la AMO, es súper linda persona y muy buena profesora, explica súper claro y sencillo y repite las veces que sea necesarias. Se preocupa demasiado por sus estudiantes y brinda mucho apoyo. Las clases con ella siempre son divertidas. Califica un toque rudo los proyectos, pero lo demás todo bien.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Inspirador', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2023-11-22T00:00:00+00:00'::TIMESTAMPTZ, 'a96491f5218801170e197004d69eb9943875807fecd830cd6074e17e021daed8'::TEXT, ARRAY[922]::BIGINT[]),
    (216::BIGINT, 'Super buena profesora, explica bien en clases y siempre está dispuesta a resolver dudas, tanto en clases como en consulta, es muy compresiva con los estudiantes, no dude en matricular con ella si tiene la oportunidad.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Asistencia obligatoria', 'Brinda apoyo']::TEXT[], '2023-06-25T00:00:00+00:00'::TIMESTAMPTZ, 'f03d556aacd66ef2981df40a9d12ae4b569db596f1aa30eae6ae2bb6c3816a84'::TEXT, ARRAY[922]::BIGINT[]),
    (216::BIGINT, 'Es una excelente profesora, comprensiva con los estudiantes. Se le entiende bastante bien en clase y da bastantes ejemplos de todos los temas que se tienen que ver, cosa que hace que se haga más fácil hacer los trabajos. Si tiene duda en consulta le aclara super bien.'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2023-06-24T00:00:00+00:00'::TIMESTAMPTZ, 'a65ab64dbca2b6e9b106b26960180ff55f951f139d5bdef06a6a73eb742ebb50'::TEXT, ARRAY[922]::BIGINT[]),
    (216::BIGINT, 'La profe explica como si fueran niños de colegio y de cierto modo es bueno porque entender es sencillo, hace ejemplos buenos, toma en cuenta la asistencia, da "puntos estrellita" por participar (a veces). Trata de ir al día con las notas pero no le sale xd. En general es buena profe.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Asistencia obligatoria', 'Clases largas']::TEXT[], '2023-06-21T00:00:00+00:00'::TIMESTAMPTZ, '40be9279c5edbf4411b108376843a7127a0c3aee14628c56103b63b2965104e6'::TEXT, ARRAY[922]::BIGINT[]),
    (216::BIGINT, 'La mejor profesora de Fisica 3, si ud lleva con ella, ud pasa sobrado. Explica claro, hace muchos ejercicios que ayudan bastante para las tareas y los examenes, y en consulta ayuda bastante con las dudas.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Respetado por los estudiantes', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2023-06-20T00:00:00+00:00'::TIMESTAMPTZ, '14ea66bf51a835f00393bed99a7038c4bfb7e5fb72057f0e60cf42a268490fb4'::TEXT, ARRAY[922]::BIGINT[]),
    (216::BIGINT, 'La profe es un amor. Se preocupa genuinamente por uno como persona estudiante y los problemas que uno tenga en la vida. El curso es sencillo (la fisica más sencilla), pero a diferencia de las otras Físicas, en esta se hacen muchos trabajos. 100% recomendada. Dígale que lleve a Gauss a clase.'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Inspirador', 'Brinda apoyo', 'Deja trabajos largos']::TEXT[], '2023-06-19T00:00:00+00:00'::TIMESTAMPTZ, 'e673cb1d3a1543156ce49d314ef885781a927b7f36c0c9240ea23798223325c2'::TEXT, ARRAY[922]::BIGINT[]),
    (216::BIGINT, 'Excelente profe, hace las clases más amenas y no tan cargadas. Explica súper bien.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2022-06-01T00:00:00+00:00'::TIMESTAMPTZ, 'a2d73e881ae86cd7546ae040685aea7d78f9dd28b72a1fe7f9ca651368c18d03'::TEXT, ARRAY[922]::BIGINT[]),
    (216::BIGINT, 'Buena profesora, se hacen varios trabajos en el semestre, si necesitas ayuda en lo que sea ella siempre busca el espacio para ayudarte, en la clase sincrónica se ve la materia de la cátedra'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-12-05T00:00:00+00:00'::TIMESTAMPTZ, '24e05ca5ee105fcd3b8713b63dbbdf9d251787419e7f8db4b3727b4399e73725'::TEXT, ARRAY[922]::BIGINT[]),
    (216::BIGINT, 'Muy buena profe, explica muy claro y ayuda bastante. En el curso se realizan muchos trabajos, por lo que si hay que ser organizado.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Muchas tareas', 'Brinda apoyo']::TEXT[], '2021-07-20T00:00:00+00:00'::TIMESTAMPTZ, 'b84bc43999fa058d0a7d80e1d1952c086238de3612db18e28442cc7cd02f62e7'::TEXT, ARRAY[922]::BIGINT[]),
    (216::BIGINT, 'Es una de las mejores profes de la escuela, es demasiado linda y explica super claro. Los ejercicios que pone en clase tienen un nivel parecido al de los cuestionarios. Si tiene la oportunidad de matricular con ella, dele sin miedo al éxito'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2021-05-28T00:00:00+00:00'::TIMESTAMPTZ, '70f051f608704813613af45a14b2a7560945b61a7dbf1b906d873d3a739bb5cc'::TEXT, ARRAY[922]::BIGINT[]),
    (216::BIGINT, 'MEGA RECOMENDADA, es una excelente profesora y explica con muchísimo claridad; es muy amable y siempre responde las dudas. Se adaptó genial a la modalidad virtual y sin duda volvería a llevar el curso con ella.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Respetado por los estudiantes', 'Clases excelentes']::TEXT[], '2021-02-07T00:00:00+00:00'::TIMESTAMPTZ, '6b92fcbae5520e2b9847f6451dc5fc70aed823f41b07fe44f4151c280d4a08d7'::TEXT, ARRAY[631]::BIGINT[]),
    (216::BIGINT, 'SUPER RECOMENDADA. Es demasiado buena persona y profesora. Explica super bien y está dispuesta a ayudar. Deja muchos trabajos, pero al ponerlo en balanza contra su esfuerzo, vale totalmente la pena. Si puede matricular con ella, ni lo dude.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Muchas tareas', 'Brinda apoyo']::TEXT[], '2020-11-14T00:00:00+00:00'::TIMESTAMPTZ, '09eba567710894a2957b8299de83f82985cabe896c3fd0a7b214f1d8a5f08426'::TEXT, ARRAY[922]::BIGINT[]),
    (216::BIGINT, 'Muy buena persona y considerada con los estudiantes. Califica suave y daba pistas con las tareas. Para la modalidad virtual preparaba sus propias presentaciones y estaban muy completas.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2020-08-07T00:00:00+00:00'::TIMESTAMPTZ, 'af81853be1dcb99c3668a5af1a28257e0453696d6c59a426fea873327d8751ee'::TEXT, ARRAY[922]::BIGINT[]),
    (216::BIGINT, 'La profe es demasiado buena tanto para la clase, como persona. Se preocupa mucho por sus estudiantes y en general el curso es muy fácil de pasar. Para mí, ella es de las mejores profes de física que hay'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2019-06-15T00:00:00+00:00'::TIMESTAMPTZ, '23cedd405980686d0fa0b75666a6437aa268a92832ec7913c3041209975fa78c'::TEXT, ARRAY[607]::BIGINT[]),
    (216::BIGINT, 'Es buena profe, da buena retroalimentación luego de cada trabajo. Explica con bastante claridad y pone instrucciones en TecDigital. Todo se mantiene bien siempre y cuando ella no falte a las clases.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Aspectos de calificación claros', 'Muchos proyectos grupales']::TEXT[], '2019-06-13T00:00:00+00:00'::TIMESTAMPTZ, '64af16c5c8a90977f5e7350ac5e436a27a6bf58533133661762eeea5bef3531f'::TEXT, ARRAY[607]::BIGINT[]),
    (216::BIGINT, 'Es una teja de persona, es super buena gente, lo único malo es que deja muchos trabajos (poco comunes algunos) pero lo compensa calificando suave, explica bastante bien y da el material más que necesario para salir bien en los exámenes.'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Asistencia obligatoria', 'Aspectos de calificación claros']::TEXT[], '2019-06-12T00:00:00+00:00'::TIMESTAMPTZ, 'bc17b79805eeeaa23e4f99ec683321317b4c54a99fdd6d007ddb9239b36175f4'::TEXT, ARRAY[922]::BIGINT[]),
    (216::BIGINT, 'No me quejo, es buena profe y todo queda muy claro porque sube las instrucciones al TecDigital.'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Aspectos de calificación claros', 'Deja trabajos largos']::TEXT[], '2019-06-01T00:00:00+00:00'::TIMESTAMPTZ, 'bc68e898ea57913c234f9589b00477bb63f896ddb0c0e0238c634a0cbe3286dd'::TEXT, ARRAY[607]::BIGINT[]),
    (216::BIGINT, 'Ninguno'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Inspirador', 'Clases excelentes']::TEXT[], '2019-05-30T00:00:00+00:00'::TIMESTAMPTZ, 'fb3a3cd77159e3d3ca31648c957a6525937fba23051c54f7a3c328c5d595ae22'::TEXT, ARRAY[922]::BIGINT[]),
    (216::BIGINT, 'La profe es joven y eso hace que los estudiantes creen un vinculo de confianza permitiendo sacarse de dudas en cualquier momento!'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Asistencia obligatoria', 'Brinda apoyo']::TEXT[], '2019-05-29T00:00:00+00:00'::TIMESTAMPTZ, '98fb601d0064d5275f2c1d5e5aba3bfda6d702c511a78d77182726b74024b819'::TEXT, ARRAY[631, 607]::BIGINT[]),
    (216::BIGINT, 'Excelente. Explica demasiado bien. Califica muy suave. Explica todas las veces que sea necesario.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Tomaría su clase nuevamente']::TEXT[], '2018-12-11T00:00:00+00:00'::TIMESTAMPTZ, '46278bf94b20413b6fec00b0aa30f7b1a131cfce268f147013f058be50e3c78c'::TEXT, ARRAY[607]::BIGINT[]),
    (216::BIGINT, 'La recomiendo!'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-11-09T00:00:00+00:00'::TIMESTAMPTZ, '23cfd1ae8697c0dffffd50a28c8ad767ec6bc0f1c3f5f504432a416ebc82b882'::TEXT, ARRAY[607]::BIGINT[]),
    (216::BIGINT, 'Una muy buena profesora con herramientas pedagógicas modernas y ajustables, mucha disposición para colaborar con los estudiantes.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Aspectos de calificación claros', 'Brinda apoyo']::TEXT[], '2018-05-06T00:00:00+00:00'::TIMESTAMPTZ, '283dde9caf0a647d1b930480cf5c3846cae24d2b8434631097c01d3db722ea7e'::TEXT, ARRAY[631, 607]::BIGINT[]),
    (216::BIGINT, 'Ninguno'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Inspirador', 'Da crédito extra']::TEXT[], '2018-01-11T00:00:00+00:00'::TIMESTAMPTZ, 'b5195ab32f9d887d1f4d1af288fcefcf26183feeee4f53f8d22da85d45641f2a'::TEXT, ARRAY[607]::BIGINT[]),
    (216::BIGINT, 'Es una muy bella persona. Siempre aboga por el estudiante y es muy considerada al calificar. Los apuntes que da son muy directos, por lo que no hay que hacerse bolas con el libro.'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('60','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-06-15T00:00:00+00:00'::TIMESTAMPTZ, 'a40bbbbf91d4820d7edfa6d0fdf78b15854a3c0688e5958b76c5e8e8207b88b6'::TEXT, ARRAY[922]::BIGINT[]),
    (216::BIGINT, 'Es buena profesora, se pasa fácil si se es responsable, se preocupa por sus estudiantes, explica relativamente claro es muy buena persona, y sobretodo tiene paciencia 100% recomendada.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Asistencia obligatoria', 'Muchos proyectos grupales']::TEXT[], '2017-06-14T00:00:00+00:00'::TIMESTAMPTZ, '877782839db5baed82e58431bb6687b0a54f7c6e629a884c6288c099d34cf9bd'::TEXT, ARRAY[607]::BIGINT[]),
    (216::BIGINT, 'Es muy buena, ayuda mucho y califica suave'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-01-27T00:00:00+00:00'::TIMESTAMPTZ, '9a9afcc4387e1cf876d178f57a0cb5734485400598bb6a18c79252e3ce7125d0'::TEXT, ARRAY[3021]::BIGINT[]),
    (216::BIGINT, 'Muy recomendada, es clara al explicar, muy accesible y excelente persona. Los quices son fáciles y trata de no poner tareas, pone a lo mucho dos tareas pero son super sencillas. Si se queda con ella es el colmo.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Respetado por los estudiantes', 'Brinda apoyo']::TEXT[], '2017-01-26T00:00:00+00:00'::TIMESTAMPTZ, '6b171c60f2d0cbf2d57500861d5dbad13ca8c64e8c63d9c5bc26b8b807ec1828'::TEXT, ARRAY[922]::BIGINT[]),
    (216::BIGINT, 'Ninguno'::TEXT, 4.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor']::TEXT[], '2017-01-18T00:00:00+00:00'::TIMESTAMPTZ, '5c5e3f18bb801265d729b9c0c00ee53b038f0343cda2988a23e629a9d92fe04b'::TEXT, ARRAY[607]::BIGINT[]),
    (216::BIGINT, 'No es la mejor explicando pero si lo hace lo suficientemente bien para aprender. Califica muy suave y ayuda un monton. En general hace que el curso sea facil y sea aprende'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-01-18T00:00:00+00:00'::TIMESTAMPTZ, '7ba9a28ec527814fd7096fc258f4cf310517fe26b862d852415d849ce14d4f90'::TEXT, ARRAY[922]::BIGINT[]),
    (216::BIGINT, 'no explica bien, se enrreda, es aburrido, pero se pasa de fijo'::TEXT, 10.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-11-22T00:00:00+00:00'::TIMESTAMPTZ, 'daccc2ae4f709408130c0a2baf8554ed50f821b9fdb9d7f05051a5248664b9bb'::TEXT, ARRAY[607]::BIGINT[]),
    (216::BIGINT, 'Con ella tenga por seguro que va a pasar, pero va a aprender poco o nada.'::TEXT, 6.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas']::TEXT[], '2016-06-27T00:00:00+00:00'::TIMESTAMPTZ, '39bb146c512b4568f87a2f8fbb7dc81557d368e73487cc37758b501535d2b4ed'::TEXT, ARRAY[607, 631, 922]::BIGINT[]),
    (216::BIGINT, 'Se las recomiendo'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-06-22T00:00:00+00:00'::TIMESTAMPTZ, '381fdf74022dcea59cef9670dbd336e556da63aa7b3249a3fc443857dbea3094'::TEXT, ARRAY[607]::BIGINT[]),
    (216::BIGINT, 'Las clases son relativamente estándar, se enreda a veces explicando pero nada del otro mundo; mas sí recomendaría estudiar bastante con el libro. Como persona es una teja y califica con el corazón. Si quiere llevar física sin mucho estrés, Melania es la respuesta.'::TEXT, 10.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2016-06-19T00:00:00+00:00'::TIMESTAMPTZ, '9bb0f3db53b05ed53c23ef467276c784ced2d7ce58c517da5ca2fe9c455e7eb4'::TEXT, ARRAY[922]::BIGINT[]),
    (216::BIGINT, 'Aún le falta un poco de experiencia para dar clases, sin embargo es una excelente persona y realmente se preocupa por el estudiante, además se ve que está mejorando. Es una muy buena opción y creo que en unos pocos años será de lo mejor que tenga la escuela de física.'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo']::TEXT[], '2016-06-09T00:00:00+00:00'::TIMESTAMPTZ, '56a32f23c9690be527e55c879fc17b469a408ab185d85723e0caacdb52b51d13'::TEXT, ARRAY[607]::BIGINT[]),
    (216::BIGINT, 'No explica muy bien, de hecho me enredaba si prestaba atención, sin embargo califica extremadamente suave y ayuda demasiado. Prácticamente se puede pasar con solo leer el libro.'::TEXT, 10.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-04-17T00:00:00+00:00'::TIMESTAMPTZ, '86240f8361f52dfbf23dc8a773651ea59423b6d4d0a801f536fdabf367979969'::TEXT, ARRAY[607]::BIGINT[]),
    (216::BIGINT, 'En verano es buena profesora, muy ordenada y trabaja bastante bien. No hizo quices sino solo "exposiciones" super cortas. Si la recomiendo'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Aspectos de calificación claros', 'Clases excelentes']::TEXT[], '2016-02-10T00:00:00+00:00'::TIMESTAMPTZ, 'd941957250825885be87927d730f08d338353db712d05f4540c203e0ec32409c'::TEXT, ARRAY[922]::BIGINT[]),
    (216::BIGINT, 'Ser su alumno fue terrible. Cada lección era tiempo desperdiciado, siempre se enreda en lo que dice y pareciera que se esfuerza para que nadie le entienda. Al final del semestre, cuando todos están por perder el curso, es aun peor profesora y desaparece para que nadie pueda pedirle ayuda'::TEXT, 2.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-01-11T00:00:00+00:00'::TIMESTAMPTZ, '6637dad196d15a447d60149851d5a07f7fb9223c00aef26ad299a1a2f63f3118'::TEXT, ARRAY[607]::BIGINT[]),
    (216::BIGINT, 'Es buena persona, pero no explica muy claro aunque lo intenta. Sin embargo casi todo el grupo pasa.'::TEXT, 10.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-01-06T00:00:00+00:00'::TIMESTAMPTZ, 'd5a86176596de55a88812e203de6442b49e0ddcea17a330aadbf249d598c24ae'::TEXT, ARRAY[922]::BIGINT[]),
    (216::BIGINT, 'Es una excelente persona, como profesora le falta experiencia pero trata de ayudarle al estudiante y no tratarlo de molestar, esta siempre disponible para los estudiantes en consulta y dispuesta a explicarles.'::TEXT, 10.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-11-29T00:00:00+00:00'::TIMESTAMPTZ, '99651d1e0a3e633c47f5cf777c6b80498d48701f8f646a1a3ba84f32c56d1639'::TEXT, ARRAY[607]::BIGINT[]),
    (216::BIGINT, 'Se enreda en algunos temas, a veces cuesta un poco entenderle, es una excelente persona, muy pura vida, califica suave (e y q), genial si esta repitiendo el curso.'::TEXT, 10.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-11-29T00:00:00+00:00'::TIMESTAMPTZ, '9e47f75b4780eff3ad5677cff0355129418ff3e3d35a0294998e5f49c725c541'::TEXT, ARRAY[607]::BIGINT[]),
    (216::BIGINT, 'Una profe un poco insegura, aún le falta experiencia, se pone muy nerviosa cuando le preguntan algo. No transmite seguridad cuando explica y se enreda mucho, pero lo buena gente nadie se lo quita, aunque con eso no es suficiente.'::TEXT, 8.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-11-26T00:00:00+00:00'::TIMESTAMPTZ, '49147cd3228b3e7d2ab0d1c9a07bb9d6bb77e99abfa277945bc45e5ba4dfffbe'::TEXT, ARRAY[607]::BIGINT[]),
    (216::BIGINT, 'Esta empezando, algunas cosas se le enredan pero se corrige sola. Es buena gente. La clase no es aburrida. Califica suave. Ayuda bastante. Es paciente.'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-11-26T00:00:00+00:00'::TIMESTAMPTZ, 'a3185f618d4bd9be7c166751d662425866dd2e762e9ab2d31456356ac727e262'::TEXT, ARRAY[607]::BIGINT[]),
    (216::BIGINT, 'Es una profe demasiado pura vida y sin duda alguna una muy buena persona. A veces se medio enreda pero se corrige sola. Clases tuanis!'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-11-23T00:00:00+00:00'::TIMESTAMPTZ, 'd0907163433a9e4450a1f1fda605b9c1f7338e52a8150f611bc908a9f7e9289a'::TEXT, ARRAY[607]::BIGINT[]),
    (216::BIGINT, 'La profe es muy pura vida, es muy carga, explica bien, y ayuda bastante, ademas mantiene la clase "entretenida" o activa, no son clases aburridas. califica justo. Recomendada 100%.'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-11-22T00:00:00+00:00'::TIMESTAMPTZ, 'bfad4df2db6d1b765212cdccf37c62a6917be587fd44716856905682c8255625'::TEXT, ARRAY[922]::BIGINT[]),
    (216::BIGINT, 'Muy buena gente, ayuda bastante y trata siempre de que quede clara la materia. No es aburrida, logra captar la atención. Califica justo, y no busca perjudicar al estudiante. 100% Recomendada'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-10-27T00:00:00+00:00'::TIMESTAMPTZ, '901472626589371d7ff1e0cb6398f84ef1333cbc6973d25fa877cc311a157892'::TEXT, ARRAY[922]::BIGINT[]),
    (216::BIGINT, 'Está empezando a dar clases entonces para explicar a veces (en algunos temas) se enreda, pero es flexible para calificar, los quices son sencillos y a veces anuncia los ejercicios de los que va a hacer el quiz, la mayoria pasa y entendiendo.'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-06-26T00:00:00+00:00'::TIMESTAMPTZ, '967b87052507d9eb02c93515a6f3be74a8c58364729a1b127a9c5849dadd4838'::TEXT, ARRAY[922]::BIGINT[]),
    (216::BIGINT, 'Ninguno'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-06-20T00:00:00+00:00'::TIMESTAMPTZ, '74d6e35f75dd62435f548bd61da7e62075375c44e289998a616dc0bd603b4271'::TEXT, ARRAY[631]::BIGINT[]),
    (216::BIGINT, 'Es muy buena gente, los quices son sencillos, califica bonito, da tiempo para entregar los informes. Se enreda un poco explicando, pero al final se entiende.'::TEXT, 10.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-06-07T00:00:00+00:00'::TIMESTAMPTZ, '4fa0a43cc645a192b2ce44338f272471a2bb8d57dc333562bf8f907236d393e6'::TEXT, ARRAY[631]::BIGINT[]),
    (216::BIGINT, 'Es buena profe, un poco insegura pero te trata de hacer entender, hace las clases muy agradables, califica muy bonito y te ayuda bastante.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-05-29T00:00:00+00:00'::TIMESTAMPTZ, 'ca879c521948578d648c20f01241edb1e8364c9d233e9d4912e7cd787cb0f32b'::TEXT, ARRAY[922]::BIGINT[]),
    (216::BIGINT, 'Es bien mala no sabe casi nada de física. A veces se sabe más que la profe'::TEXT, 8.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('40','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-05-29T00:00:00+00:00'::TIMESTAMPTZ, 'f41bce471cd945d2c02da353c12e45874f79285c5c60f4a239c4c825d6a6fa71'::TEXT, ARRAY[922]::BIGINT[]),
    (216::BIGINT, 'Es buena profesora, estudio enseñanza así que no es como otros profesores también da clases en la UCR. A veces se enreda y es insegura pero corrige sus propios errores y las clases son agradables'::TEXT, 8.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-03-23T00:00:00+00:00'::TIMESTAMPTZ, '4c9e9f13b757644c930be7d350fdf8644d3451a4693dd9a74c23008b1434f184'::TEXT, ARRAY[922]::BIGINT[])
), inserted_review AS (
  INSERT INTO public.professor_review (
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, status, reviewed_at, created_at, updated_at, import_key
  )
  SELECT 
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, 'approved'::public.professor_review_status, now(), created_at, created_at, import_key
  FROM review_input ri
  WHERE NOT EXISTS (
    SELECT 1 FROM public.professor_review pr WHERE pr.import_key = ri.import_key
  )
  RETURNING id, import_key
), target_review AS (
  SELECT id, import_key FROM inserted_review
  UNION ALL
  SELECT pr.id, pr.import_key
  FROM public.professor_review pr
  JOIN review_input ri ON ri.import_key = pr.import_key
)
INSERT INTO public.professor_review_course (review_id, course_id)
SELECT tr.id, course_id
FROM target_review tr
JOIN review_input ri ON ri.import_key = tr.import_key
CROSS JOIN LATERAL unnest(ri.course_ids) AS course_id
ON CONFLICT DO NOTHING;

COMMIT;
